import re

def totals(csv_text):
    if not csv_text or csv_text.strip() == "":
        return {}

    # Initialize a dictionary to store total amounts per name
    totals_map = {}

    # Split the input by lines and process each line
    lines = csv_text.strip().split('\n')

    for line in lines:
        line = line.strip()
        if not line:
            continue

        # Use regex to find name and amount (handle quoted names)
        match = re.search(r'([^",]*)("[^"]*"|[^",]+)(,\s*|\s*,\s*)([\d\.,-]+)(\s*[,\n])?', line)

        if match:
            name_part = match.group(1)
            amount_part = match.group(4)

            # Extract name (if it's not in quotes, otherwise extract inside quotes)
            if match.group(2):
                # Name is in quotes
                name = match.group(2).strip('"')
            else:
                # Name is not in quotes
                name = name_part

            # Parse amount as decimal (without using binary floats)
            try:
                amount = float(amount_part)
            except ValueError:
                continue

            # Add amount to the corresponding name
            if name in totals_map:
                totals_map[name] += amount
            else:
                totals_map[name] = amount

    # Format results as string with two decimal places
    result = {}
    for name, total in totals_map.items():
        result[name] = f"{total:.2f}"

    return result

